function generateAdultTemplates() {
  const topics = [
    { id: 'BE_ADULT_001', title: 'Comprendre pourquoi {dog_name} aboie', body: "L'aboiement est un mode de communication naturel. {dog_name} peut aboyer pour prévenir d'une présence, par ennui, par excitation ou par frustration. Avant de vouloir faire taire les aboiements, cherchez à comprendre leur cause. Un chien qui aboie à la fenêtre veille sur son territoire. Un chien qui aboie quand il est seul exprime un mal-être. Un chien qui aboie en promenade est souvent frustré ou surexcité. La solution dépend de la cause. Observez le contexte, l'intensité et la durée des aboiements pour mieux comprendre ce que {dog_name} essaie de vous dire. Un éducateur canin peut vous aider à décoder ces signaux." },
    { id: 'BE_ADULT_002', title: 'Destructions : ennui ou inconfort ?', body: "Si {dog_name} détruit en votre absence, ce n'est pas de la vengeance. Les chiens ne fonctionnent pas ainsi. Deux causes principales : l'ennui ou un inconfort lié à la solitude. Un chien qui manque d’occupation mâche pour s'occuper — offrez-lui des jouets d'occupation (Kong fourré, tapis de léchage). Un chien inconfortable seul montre d'autres signes : halètement, salivation, déplacement constant. Dans ce cas, le problème est plus profond et nécessite un travail progressif sur la séparation. Observez {dog_name} avec une caméra pour comprendre ce qui se passe vraiment quand vous partez." },
    { id: 'BE_ADULT_003', title: 'Tirer en laisse : des solutions durables', body: "{dog_name} tire en laisse ? C'est le problème numéro un en promenade. La solution : ne plus avancer quand la laisse est tendue. Dès que {dog_name} tire, arrêtez-vous. Attendez que la laisse se détende, puis repartez. C'est long au début mais efficace. Récompensez chaque moment où {dog_name} marche à côté de vous. Un harnais anti-traction peut aider en complément. Mais surtout, rendez la promenade intéressante : laissez-le renifler, changez de direction, proposez des friandises quand il vous regarde. Un chien qui tire veut aller plus vite — montrez-lui que rester près de vous est tout aussi gratifiant." },
    { id: 'BE_ADULT_004', title: '{dog_name} a réaction d’évitement de l\'orage', body: "Beaucoup de chiens sont sensibles aux orages — le bruit, les changements de pression atmosphérique, l'électricité statique. Si {dog_name} se cache, tremble ou cherche votre contact pendant un orage, restez calme et disponible. Ne le forcez pas à sortir de sa cachette, ne le grondez pas, mais ne surjouez pas non plus la compassion. Offrez-lui un endroit sûr : une pièce intérieure, un panier couvert. La musique douce peut couvrir le bruit du tonnerre. Des friandises ou un jouet d'occupation peuvent aussi détourner son attention. Avec le temps, certains chiens s'habituent." },
    { id: 'BE_ADULT_005', title: 'Réactivité en laisse : comprendre et agir', body: "Un chien qui tire, aboie ou s'agite en croisant d'autres chiens en laisse est un chien réactif, pas un mauvais chien. La réactivité est souvent liée à la frustration (il veut aller dire bonjour) ou à l'inconfort (il se sent coincé par la laisse). La distance est votre amie : pratiquez le « regarde-moi » en éloignant {dog_name} suffisamment du déclencheur. Récompensez tout regard calme dans votre direction. Ne tirez pas sur la laisse — cela augmente la tension. Progressivement, réduisez la distance. Ce travail prend du temps mais les résultats sont durables." },
    { id: 'BE_ADULT_006', title: 'La routine : le secret d\'un chien serein', body: "Les chiens aiment la prévisibilité. Une routine régulière — promenades aux mêmes heures, repas à heures fixes, moments de jeu et de repos définis — aide {dog_name} à se sentir en sécurité. Un chien qui sait ce qui va arriver est un chien plus détendu. Cela ne veut pas dire que chaque journée doit être identique, mais le cadre général doit être stable. Les repas, la promenade du matin, le moment calme de l'après-midi, la promenade du soir — ces repères structurent la journée de {dog_name} et lui permettent de se reposer entre les moments d'activité." },
    { id: 'BE_ADULT_007', title: 'Les signaux d\'apaisement du chien', body: "Les chiens communiquent constamment avec leur corps. Les signaux d'apaisement sont des gestes que {dog_name} utilise pour montrer qu'il est calme, qu'il veut calmer l'autre, ou qu'il est mal à l'aise. Détourner la tête, lécher ses babines, bâiller, se secouer (hors de l'eau), renifler le sol — tous sont des signaux d'apaisement. Quand vous les observez chez {dog_name}, demandez-vous ce qui se passe dans son environnement. Apprendre à lire ces signaux transforme votre relation : vous comprenez {dog_name} avant qu'il n'ait besoin de monter en intensité." },
    { id: 'BE_ADULT_008', title: 'Jeu entre chiens : le bon et le moins bon', body: "Quand {dog_name} joue avec d'autres chiens, observez la dynamique. Un bon jeu est réciproque : les deux chiens s'amusent, ils alternent les rôles (poursuivant/poursuivi), ils font des pauses naturelles. Un jeu qui dérape : un chien est toujours au sol, les grognements deviennent graves, un chien tente de fuir sans y arriver, le jeu s'intensifie sans pause. Intervenez en douceur si vous voyez que {dog_name} ou son partenaire montre des signes d'inconfort. Mieux vaut une pause courte que de laisser la situation dégénérer." },
    { id: 'BE_ADULT_009', title: '{dog_name} dort beaucoup : c\'est normal !', body: "Un chien adulte dort entre 12 et 18 heures par jour. Oui, autant. Et c'est parfaitement normal. Le sommeil est essentiel pour la suivi vétérinaire physique et mentale de {dog_name}. Ne vous inquiétez pas si votre chien passe la majorité de la journée à se reposer entre les promenades. C'est son rythme naturel. Respectez ses moments de sommeil et offrez-lui un couchage confortable dans un endroit calme. Un chien bien reposé est un chien plus concentré, plus patient et plus agréable à vivre." },
    { id: 'BE_ADULT_010', title: 'L\'enrichissement au quotidien', body: "L'enrichissement n'est pas un luxe, c'est un besoin. {dog_name} a un cerveau qui demande à être stimulé. Variez les jouets d'occupation, proposez des puzzles alimentaires, cachez des friandises dans la maison ou le jardin, apprenez-lui de nouveaux tours. Cinq minutes de stimulation mentale par jour changent tout. Un Kong fourré, un tapis de fouille, une balle à friandises — ces objets simples occupent {dog_name} de façon constructive. Un chien stimulé est un chien qui ne cherche pas à inventer ses propres divertissements (comme détruire le canapé)." },
    { id: 'BE_ADULT_011', title: 'Promenade libre vs en laisse', body: "Idéalement, {dog_name} devrait profiter des deux. La promenade en laisse structure et rassure, la promenade libre permet d'explorer, de courir et de renifler à son rythme. Si le rappel de {dog_name} est fiable, cherchez des espaces sécurisés pour le lâcher. Sinon, une longe de 5 à 10 mètres offre un bon compromis. En ville, la laisse est obligatoire et nécessaire pour la sécurité. En campagne ou en forêt, la liberté contrôlée est un bonheur pour {dog_name}. L'important est de varier les types de promenade." },
    { id: 'BE_ADULT_012', title: 'Communiquer avec {dog_name}', body: "Votre voix, votre posture et vos gestes sont autant de messages pour {dog_name}. Parlez-lui d'un ton calme et clair. Les ordres courts (assis, viens, stop) sont plus efficaces que les phrases longues. Votre langage corporel compte énormément : penchez-vous légèrement en vous tournant de côté pour l'inviter, restez droit pour marquer un arrêt. {dog_name} lit votre humeur mieux que quiconque. Quand vous êtes détendu, il l'est aussi. Quand vous êtes tendu, il le perçoit. La communication est un dialogue permanent entre vous." },
    { id: 'BE_ADULT_013', title: 'Lire le langage corporel de {dog_name}', body: "La queue, les oreilles, la posture générale, les yeux — {dog_name} vous parle constamment. Queue haute et rigide : vigilance ou excité. Queue basse entre les pattes : inconfort. Oreilles plaquées : réaction d’évitement ou soumission. Oreilles dressées vers l'avant : intérêt. Corps détendu, bouche légèrement ouverte : chien serein. Corps raide, regard fixe : tension. Apprenez à observer {dog_name} dans différentes situations pour créer votre dictionnaire personnel. Chaque chien a ses propres nuances d'expression." },
    { id: 'BE_ADULT_014', title: '{dog_name} et le canapé : poser des règles claires', body: "Le canapé n'est ni un droit ni un interdit absolu — c'est votre choix. L'important est la constance. Si {dog_name} a le droit de monter, c'est toujours. S'il n'a pas le droit, c'est jamais. La confusion naît des exceptions. Si vous souhaitez limiter l'accès, enseignez le « descends » avec une récompense au sol. Proposez un panier confortable à côté du canapé — ainsi {dog_name} reste près de vous sans être dessus. Ce qui compte, c'est que la règle soit claire et constante pour tout le monde dans la maison." },
    { id: 'BE_ADULT_015', title: 'Gérer les invités avec {dog_name}', body: "L'arrivée d'invités est un moment excitant pour {dog_name}. Pour éviter les bonds et l'agitation, établissez un protocole. Avant l'arrivée, promenez {dog_name} pour diminuer son énergie. Quand la sonnette retentit, demandez un « assis » ou envoyez-le à son panier. Récompensez le calme. Demandez à vos invités de ne saluer {dog_name} que lorsqu'il est calme (quatre pattes au sol). Vous pouvez aussi lui donner un jouet d'occupation à l'arrivée des invités pour canaliser son excitation. La répétition crée la routine." },
    { id: 'BE_ADULT_016', title: 'Chien et chat : la cohabitation', body: "La cohabitation chien-chat est possible mais demande de la patience. Laissez le chat avoir des zones en hauteur inaccessibles au chien. Les premières rencontres se font à travers une porte fermée (échange d'odeurs), puis avec une barrière visuelle, puis en présence surveillée. Récompensez {dog_name} quand il ignore le chat ou reste calme en sa présence. Ne laissez jamais {dog_name} poursuivre le chat — même en jeu. Le chat doit toujours pouvoir fuir. Avec le temps, beaucoup de chiens et de chats trouvent un équilibre paisible." },
    { id: 'BE_ADULT_017', title: '{dog_name} aboie à la sonnette', body: "La sonnette est un déclencheur classique d'aboiements. {dog_name} a appris que sonnette = quelqu'un arrive = excitation. Pour changer cette association, entraînez en dehors des visites réelles. Demandez à quelqu'un de sonner pendant que vous envoyez {dog_name} sur son tapis avec une friandise. Récompensez-le quand il reste calme. Répétez des dizaines de fois. Vous pouvez aussi remplacer la sonnette par un carillon moins stimulant. L'objectif : sonnette = aller au tapis, pas sonnette = aboyer comme un fou." },
    { id: 'BE_ADULT_018', title: 'Protection de ressources : comprendre et agir', body: "Si {dog_name} grogne ou se raidit quand vous approchez de sa gamelle ou de son jouet, il protège ses ressources. C'est un comportement naturel, pas un signe de méchanceté. Ne retirez pas la gamelle de force — cela empire les choses. Au contraire, passez près de lui et ajoutez quelque chose de bon dans sa gamelle. Apprenez-lui que votre approche signifie « bonus ». Échangez les jouets plutôt que de les prendre. Si le comportement est intense, consultez un éducateur canin comportementaliste. Ce n'est pas à ignorer mais ce n'est pas non plus dramatique." },
    { id: 'BE_ADULT_019', title: '{dog_name} creuse dans le jardin', body: "Creuser est un instinct naturel chez de nombreuses races. {dog_name} peut creuser par ennui, pour chercher de la fraîcheur, pour cacher un os ou simplement par plaisir. Plutôt que d'interdire totalement, proposez une zone de fouille dédiée : un bac à sable ou un coin du jardin où il a le droit de creuser. Enterrez-y des jouets ou friandises pour l'y attirer. Augmentez l'enrichissement et l'exercice pour réduire l'ennui. Un chien qui creuse tout le jardin est souvent un chien qui manque de stimulation." },
    { id: 'BE_ADULT_020', title: 'Mâcher est un besoin naturel', body: "Mâcher n'est pas un caprice — c'est un besoin fondamental pour {dog_name}. La mastication soulage le forte sollicitation, nettoie les dents et occupe l'esprit. Offrez-lui des options variées et adaptées à sa taille : os à mâcher naturels, bâtonnets séchés, jouets en caoutchouc durables. Évitez les os cuits qui se cassent en éclats. Supervisez les premières utilisations d'un nouveau jouet à mâcher. Un chien qui a des options de mastication appropriées laissera vos chaussures tranquilles." },
    { id: 'BE_ADULT_021', title: '{dog_name} tire vers les autres chiens', body: "Quand {dog_name} tire vers chaque chien croisé en promenade, c'est généralement de la frustration sociale — il veut aller saluer. Arrêtez-vous dès qu'il tire. Attendez le retour au calme. Récompensez quand il vous regarde. Progressivement, il comprendra que le calme mène à la possibilité de saluer (quand c'est approprié). Tous les chiens ne sont pas compatibles pour un bonjour — apprenez à lire les signaux de l'autre chien et de son propriétaire avant d'autoriser le contact." },
    { id: 'BE_ADULT_022', title: 'Forêt vs ville : deux promenades différentes', body: "La promenade en forêt et la promenade en ville n'ont pas le même objectif pour {dog_name}. En ville, c'est la structure : marche au pied, gestion des stimuli, obéissance aux feux. En forêt ou en nature, c'est l'exploration : renifler, courir, patauger, suivre des pistes. {dog_name} a besoin des deux. L'idéal est de varier : ville en semaine pour la routine, nature le week-end pour la décompression. Adaptez votre matériel — un harnais confortable et une longe pour la nature, une laisse courte pour la ville." },
    { id: 'BE_ADULT_023', title: 'Le renforcement positif au quotidien', body: "Le renforcement positif n'est pas qu'un outil d'éducation — c'est un mode de vie. Chaque fois que {dog_name} fait quelque chose de bien, remarquez-le. Il se couche calmement ? « Bon chien. » Il regarde un vélo passer sans réagir ? Friandise. Il attend patiemment devant la porte ? Félicitation. Nous avons tendance à ne remarquer que les erreurs. Inversez : cherchez activement les bons comportements et récompensez-les. {dog_name} fera de plus en plus ce qui « paie » et de moins en moins ce qui est ignoré." },
    { id: 'BE_ADULT_024', title: 'Le rituel du coucher de {dog_name}', body: "Un rituel de coucher aide {dog_name} à comprendre que la journée est finie et qu'il est temps de se reposer. Dernière sortie pipi, dernière caresse, une friandise dans son panier et extinction des lumières. Chaque soir, même séquence. Les chiens adorent la prévisibilité. Si {dog_name} a du mal à se poser le soir, c'est peut-être qu'il n'a pas assez dépensé son énergie dans la journée — ou au contraire qu'il est surstimulé. Un temps calme de 30 minutes avant le coucher aide à la transition." },
    { id: 'BE_ADULT_025', title: '{dog_name} saute sur les gens : rappel', body: "Même adulte, certains chiens continuent de sauter pour dire bonjour. C'est un comportement appris dans l'enfance et renforcé involontairement (on le caresse quand il saute). La solution reste la même : ignorer le saut, récompenser les pattes au sol. Tournez le dos, croisez les bras, ne parlez pas. Dès que {dog_name} a les quatre pattes au sol, récompensez avec attention et friandise. Demandez à tout le monde — famille, amis, passants — de suivre la même règle. La cohérence est la clé." },
    { id: 'BE_ADULT_026', title: 'Promenades du soir en sécurité', body: "En hiver, les promenades du soir se font dans l'obscurité. Équipez {dog_name} d'un collier ou harnais réfléchissant, ou d'une petite lumière LED à accrocher au collier. Portez vous-même des vêtements clairs. Restez sur des chemins que vous connaissez bien. Gardez {dog_name} en laisse près des routes — les conducteurs voient moins bien la nuit. Emportez une lampe de poche pour surveiller ce que {dog_name} renifle au sol. La sécurité nocturne est une affaire de visibilité et de vigilance." },
    { id: 'BE_ADULT_027', title: '{dog_name} et les vélos ou trottinettes', body: "Certains chiens sont fascinés ou excités par les vélos et trottinettes qui passent. Si {dog_name} tire ou aboie au passage d'un cycliste, travaillez la désensibilisation. Asseyez-vous sur un banc dans un parc et récompensez {dog_name} à chaque passage de vélo qu'il observe sans réagir. Commencez à distance et rapprochez-vous progressivement. Ne grondez pas la réaction — récompensez le calme. En attendant que le travail porte ses fruits, anticipez en éloignant {dog_name} quand vous voyez un vélo arriver." },
    { id: 'BE_ADULT_028', title: '{dog_name} refuse de marcher en promenade', body: "Si {dog_name} plante ses pattes et refuse d'avancer, ne tirez pas sur la laisse. Cherchez la cause : a-t-il réaction d’évitement de quelque chose ? Le sol est-il trop chaud ou trop froid ? Est-il fatigué ? Un changement de parcours peut suffire. Proposez une friandise quelques pas devant lui. Si cela se répète régulièrement, vérifiez que ses pattes ne sont pas blessées et que son harnais est confortable. Un chien qui refuse systématiquement de marcher essaie de vous dire quelque chose." },
    { id: 'BE_ADULT_029', title: '{dog_name} et les bruits de travaux', body: "Les travaux dans le voisinage ou à la maison peuvent perturber {dog_name}. Bruits de perceuse, de marteau-piqueur, de camions — c'est beaucoup pour ses oreilles sensibles. Si possible, éloignez {dog_name} de la zone de bruit. Créez un espace refuge calme avec musique douce. Les jouets d'occupation aident à détourner l'attention. Si les travaux sont chez vous, sortez {dog_name} pendant les phases les plus bruyantes. Avec le temps, certains chiens s'habituent. D'autres restent sensibles — respectez le rythme de {dog_name}." },
    { id: 'BE_ADULT_030', title: 'La routine du matin avec {dog_name}', body: "Le matin donne le ton de la journée. Une bonne routine matinale pour {dog_name} : sortie pipi rapide, petit-déjeuner, puis promenade. Certains chiens préfèrent manger après la promenade — observez ce qui convient à {dog_name}. Évitez l'exercice intense juste après le repas. Le matin est souvent le meilleur moment pour les rencontres avec d'autres chiens, car tout le monde est frais et de bonne humeur. Même 20 minutes de promenade matinale de qualité posent les bases d'une bonne journée." },
  ];
  return topics.map(t => ({
    id: t.id, category: 'behavior_education' as const, subcategory: 'adult',
    breedFilter: [] as string[], sizeFilter: [] as string[], ageMinMonths: 24, ageMaxMonths: null as number | null,
    seasonFilter: [] as string[], monthFilter: [] as number[], regionFilter: ['all'],
    titleFr: t.title, bodyFr: t.body, sourceType: 'behavior_tip' as const,
    neverSay: [...NS], suffix: null as string | null, requiresVetDisclaimer: false,
    channel: 'home_insight' as const, priority: 6, cooldownHours: 252, maxPerMonth: 2,
    usesDogName: true, usesBreedName: true, usesAge: false, usesLocation: false, usesSeason: false,
  }));
}

function generateSeniorTemplates() {
  const topics = [
    { id: 'BE_SENIOR_001', title: 'Le ralentissement de {dog_name} : tout à fait normal', body: "{dog_name} ralentit un peu ? C'est naturel avec l'âge. Les promenades sont peut-être un peu plus courtes, les siestes un peu plus longues. Acceptez ce nouveau rythme avec bienveillance. Ne forcez jamais {dog_name} à dépasser ses limites. Adaptez les activités : des promenades plus courtes mais plus fréquentes, à un rythme qui lui convient. Le senior a encore beaucoup de enthousiasme à partager — simplement à un tempo différent.", vet: false },
    { id: 'BE_SENIOR_002', title: 'Adapter les promenades au senior', body: "Les longues randonnées font peut-être partie du passé pour {dog_name}, et c'est normal. Privilégiez des promenades plus courtes (15-30 minutes) mais régulières (2-3 fois par jour). Choisissez des terrains souples (herbe, terre) plutôt que le bitume dur. Évitez les montées et descentes raides. Laissez {dog_name} renifler à son rythme — c'est sa façon de profiter de la promenade. En hiver, les articulations peuvent être plus raides le matin. Attendez que la température se réchauffe pour sortir.", vet: false },
    { id: 'BE_SENIOR_003', title: 'Un couchage confortable pour {dog_name}', body: "Avec l'âge, le confort du couchage devient crucial. Investissez dans un matelas orthopédique ou à mémoire de forme pour {dog_name}. Placez-le au ras du sol — pas de saut pour y accéder. Choisissez un endroit sans courant d'air mais pas trop près du radiateur. Si {dog_name} a du mal à se lever, un tapis antidérapant autour de son panier l'aidera. Un bon sommeil est encore plus important pour un senior que pour un adulte.", vet: false },
    { id: 'BE_SENIOR_004', title: 'Enrichissement doux pour le senior', body: "L'enrichissement reste essentiel pour {dog_name}, même en douceur. Les puzzles alimentaires simples, les tapis de fouille et les jeux de recherche à la maison maintiennent son cerveau actif. Proposez des séances courtes (5-10 minutes) pour ne pas le fatiguer. Le reniflage en promenade est un enrichissement naturel et gratuit. {dog_name} n'a pas besoin de courir un marathon — juste de continuer à explorer et à apprendre à son rythme.", vet: false },
    { id: 'BE_SENIOR_005', title: 'Observer les changements chez {dog_name}', body: "Avec l'âge, certains changements sont normaux chez {dog_name} : sommeil accru, rythme plus lent, appétit parfois variable. Restez attentif sans vous alarmer. Un carnet de bord peut être utile : notez les heures de repas, l'énergie en promenade, la qualité du sommeil. Si vous remarquez un changement soudain ou progressif qui vous inquiète, notez-le pour en parler lors de la prochaine visite annuelle.", vet: true },
    { id: 'BE_SENIOR_006', title: 'La patience avec un chien senior', body: "{dog_name} met plus de temps à se lever ? Il ne répond plus aussi vite ? Ses capacités sensorielles changent peut-être. La patience est le plus beau cadeau que vous puissiez faire à votre compagnon vieillissant. Parlez-lui d'une voix douce et claire. Donnez-lui le temps de comprendre. Ne le brusquez pas. Chaque moment partagé a de la valeur, même les plus calmes.", vet: false },
    { id: 'BE_SENIOR_007', title: 'Articulations et temps froid', body: "Par temps froid, les articulations de {dog_name} peuvent être plus raides, surtout le matin. Attendez qu'il s'échauffe naturellement avant la promenade — un peu de marche lente dans la maison suffit. Dehors, évitez le verglas et les sols glissants. Un manteau chaud peut être utile pour les races à poil court ou les chiens très âgés. Gardez la maison à une température agréable et assurez-vous que son couchage est bien rembourré.", vet: true },
    { id: 'BE_SENIOR_008', title: 'La routine : encore plus importante pour le senior', body: "Si la routine est importante pour tout chien, elle est essentielle pour {dog_name} à cet âge. Les mêmes horaires de repas, les mêmes parcours de promenade, les mêmes rituels du coucher. La prévisibilité rassure un chien dont les sens peuvent changer. Si sa vision ou son audition diminue, il s'appuie encore plus sur ses repères habituels. Évitez de réaménager la maison ou de changer ses habitudes brusquement.", vet: false },
    { id: 'BE_SENIOR_009', title: 'Les siestes plus longues du senior : normal', body: "Si {dog_name} dort plus qu'avant, ne vous inquiétez pas. Un chien senior peut dormir jusqu'à 18-20 heures par jour. Son corps récupère plus lentement et a besoin de davantage de repos. Respectez ses phases de sommeil, ne le réveillez pas inutilement et assurez-vous qu'il a un endroit calme et confortable pour dormir. Le sommeil est réparateur et essentiel à son bien-être.", vet: false },
    { id: 'BE_SENIOR_010', title: 'Jeux calmes pour un senior à l’aise', body: "Le jeu ne s'arrête pas avec l'âge — il se transforme. {dog_name} appréciera les jeux calmes et courts : cache-cache dans la maison, recherche de friandises, le jeu de la « boîte aux trésors » (une boîte en carton avec des friandises cachées dans du papier). Les jeux d'intelligence doux stimulent son cerveau sans fatiguer son corps. Observez ce qui fait briller ses yeux et proposez-en régulièrement.", vet: false },
    { id: 'BE_SENIOR_011', title: 'Promenades courtes et fréquentes', body: "Deux longues promenades par jour sont peut-être devenues trop pour {dog_name}. Passez à trois ou quatre sorties plus courtes. Dix à quinze minutes de promenade tranquille, quatre fois par jour, apportent plus de bénéfices qu'une seule longue sortie épuisante. {dog_name} a aussi besoin de sorties pipi plus fréquentes en vieillissant. Adaptez votre emploi du temps à ses besoins actuels.", vet: false },
    { id: 'BE_SENIOR_012', title: 'Les escaliers et les accès difficiles', body: "Monter et descendre les escaliers peut devenir difficile pour {dog_name} avec l'âge. Si possible, installez son couchage et sa gamelle au rez-de-chaussée. Une rampe d'accès peut aider pour la voiture ou un marche-pied pour le canapé (s'il y a accès). Des tapis antidérapants dans les couloirs et les escaliers préviennent les glissades. Surveillez {dog_name} dans les escaliers et aidez-le si nécessaire. Mieux vaut prévenir qu'attendre une chute.", vet: false },
    { id: 'BE_SENIOR_013', title: 'Le senior et les chiots : cohabitation', body: "Si vous accueillez un chiot alors que {dog_name} est senior, supervisez attentivement les interactions. Un chiot débordant d'énergie peut fatiguer ou agacer un chien plus âgé. Offrez à {dog_name} des espaces de repos où le chiot ne peut pas le déranger. Supervisez les jeux et intervenez si le chiot est trop insistant. Respectez les signaux de {dog_name} quand il en a assez. Beaucoup de seniors apprécient la compagnie d'un jeune, mais à leur rythme.", vet: false },
    { id: 'BE_SENIOR_014', title: 'Alimentation adaptée à l\'âge de {dog_name}', body: "Les besoins nutritionnels de {dog_name} évoluent avec l'âge. Un chien senior a généralement besoin de moins de calories mais de protéines de qualité pour maintenir sa masse musculaire. Fractionnez les repas si nécessaire — deux petits repas sont parfois mieux digérés qu'un seul gros. Assurez-vous que l'eau est toujours fraîche et accessible facilement. Surélevez les gamelles si {dog_name} a du mal à se pencher.", vet: true },
    { id: 'BE_SENIOR_015', title: 'Vision et audition qui changent', body: "Avec l'âge, la vision et l'audition de {dog_name} peuvent diminuer. Si vous remarquez qu'il ne réagit plus à son nom de loin, parlez-lui de plus près et utilisez des gestes. Si sa vision baisse, évitez de déplacer les meubles et laissez des lumières allumées la nuit. Les chiens compensent remarquablement bien grâce à leur odorat et leur mémoire spatiale. Adaptez vos signaux de communication et continuez à interagir normalement avec {dog_name}.", vet: true },
    { id: 'BE_SENIOR_016', title: 'Stimulation mentale douce', body: "Le cerveau de {dog_name} a besoin d'être entretenu comme un muscle. Les exercices simples d'obéissance (assis, couché, donne la patte), même s'il les connaît depuis des années, sont une bonne stimulation. Proposez des jeux olfactifs : cachez une friandise sous un gobelet retourné parmi trois. Changez de parcours de promenade pour stimuler de nouvelles odeurs. La routine est rassurante mais de petites variations maintiennent la curiosité de {dog_name}.", vet: false },
    { id: 'BE_SENIOR_017', title: 'Câlins et contact physique', body: "Le contact physique prend une dimension encore plus importante avec l'âge. {dog_name} apprécie peut-être davantage les caresses, les massages doux et votre simple présence à ses côtés. Massez doucement ses épaules et ses hanches — cela soulage les tensions musculaires. Brossez-le avec douceur, c'est un moment de bien-être partagé. Ces moments de connexion renforcent votre lien et apportent un réel confort à {dog_name}.", vet: false },
    { id: 'BE_SENIOR_018', title: '{dog_name} senior en voiture', body: "Monter et descendre de voiture peut devenir difficile pour {dog_name}. Une rampe pliable est un investissement précieux — elle évite les sauts qui sont durs pour les articulations. Installez un tapis antidérapant sur la banquette ou dans le coffre. Pour les longs trajets, prévoyez des pauses plus fréquentes. Assurez-vous que la température dans la voiture est agréable. {dog_name} mérite un transport confortable à tous les âges.", vet: false },
    { id: 'BE_SENIOR_019', title: 'Garder une vie sociale pour le senior', body: "Ce n'est pas parce que {dog_name} ralentit qu'il doit rester isolé. Les rencontres avec des chiens calmes et compatibles restent bénéfiques. Même se contenter de renifler un congénère au passage est une interaction sociale riche pour {dog_name}. Adaptez les contextes : préférez les promenades à deux plutôt que les parcs bondés. La présence d'autres êtres vivants stimule {dog_name} et maintient sa enthousiasme de vivre.", vet: false },
    { id: 'BE_SENIOR_020', title: 'Profiter de chaque moment avec {dog_name}', body: "Le temps avec un chien senior est précieux. Savourez les promenades tranquilles, les moments de tendresse, les regards complices. {dog_name} n'a peut-être plus l'énergie de ses jeunes années, mais il a quelque chose de plus : la sérénité, la sagesse et un amour inconditionnel forgé par des années de vie commune. Photographiez, câlinez, promenez. Chaque jour est un cadeau. Profitez de {dog_name} tel qu'il est aujourd'hui, avec toute la gratitude qu'il mérite.", vet: false },
  ];
  return topics.map(t => ({
    id: t.id, category: 'behavior_education' as const, subcategory: 'senior',
    breedFilter: [] as string[], sizeFilter: [] as string[], ageMinMonths: 96, ageMaxMonths: null as number | null,
    seasonFilter: [] as string[], monthFilter: [] as number[], regionFilter: ['all'],
    titleFr: t.title, bodyFr: t.body, sourceType: 'behavior_tip' as const,
    neverSay: [...NS], suffix: t.vet ? 'Votre vétérinaire peut vous conseiller sur les besoins spécifiques de {dog_name} à cet âge.' : null,
    requiresVetDisclaimer: t.vet,
    channel: 'home_insight' as const, priority: 7, cooldownHours: 336, maxPerMonth: 2,
    usesDogName: true, usesBreedName: true, usesAge: true, usesLocation: false, usesSeason: false,
  }));
}

function generateSocializationTemplates() {
  const topics = [
    { id: 'BE_SOCIAL_001', title: 'Comprendre la socialisation canine', body: "La socialisation, c'est apprendre à {dog_name} que le monde est un endroit sûr. Ce n'est pas forcer le contact avec tout et tout le monde, mais exposer progressivement à des stimuli variés en créant des associations positives. Un chien bien socialisé est un chien confiant, pas forcément un chien qui va vers tout le monde. L'objectif est que {dog_name} puisse évoluer dans le monde humain avec sérénité, en sachant ignorer ce qui ne le concerne pas." },
    { id: 'BE_SOCIAL_002', title: 'La fenêtre de socialisation du chiot', body: "Entre 3 et 14 semaines, le chiot est dans une période de grande ouverture au monde. C'est le moment où {dog_name} forme ses impressions durables sur ce qui est normal et ce qui ne l'est pas. Chaque expérience positive pendant cette fenêtre vaut de l'or. Exposez-le à différents types de personnes, d'animaux, de bruits, de surfaces et d'environnements. Allez-y progressivement et positivement. Ce qui n'est pas vu pendant cette période sera considéré comme nouveau — et potentiellement inquiétant — plus tard." },
    { id: 'BE_SOCIAL_003', title: 'Socialiser un chien adulte : c\'est possible', body: "La socialisation ne s'arrête pas à l'enfance. Si {dog_name} est adulte et manque de socialisation, tout n'est pas perdu — mais le travail sera plus progressif. Commencez par des expositions à distance, sans contact direct. Récompensez le calme. Augmentez très progressivement la proximité. Ne forcez jamais une interaction. Un éducateur canin peut vous accompagner dans ce parcours. La patience est la clé : chaque petit progrès compte et construit la confiance de {dog_name}." },
    { id: 'BE_SOCIAL_004', title: 'Exposer sans forcer : la règle d\'or', body: "La règle numéro un de la socialisation : ne jamais forcer {dog_name}. Si un chien, une personne ou un bruit l'inquiète, augmentez la distance. Ne le poussez pas vers ce qui lui fait réaction d’évitement « pour qu'il s'habitue ». Laissez-le observer de loin, récompensez son calme, et rapprochez-vous à son rythme sur plusieurs sessions. Forcer un chien à affronter sa réaction d’évitement produit l'effet inverse : ça renforce la réaction d’évitement. La socialisation doit toujours être une expérience positive et volontaire." },
    { id: 'BE_SOCIAL_005', title: 'Reconnaître les signaux de réaction d’évitement', body: "Quand {dog_name} est inconfortable, il vous le dit avec son corps. Queue basse ou entre les pattes, oreilles plaquées, corps recroquevillé, bâillements répétés, léchage de babines, détournement du regard. Si vous voyez ces signaux lors d'une socialisation, augmentez la distance et laissez {dog_name} se détendre. Ne le forcez pas à rester dans une situation qui le met mal à l'aise. Respecter ses signaux renforce sa confiance en vous." },
    { id: 'BE_SOCIAL_006', title: 'Les bons parcs à chiens pour {dog_name}', body: "Les parcs à chiens peuvent être formidables ou désastreux, selon la gestion. Choisissez des parcs avec peu de chiens au début. Observez l'ambiance avant d'entrer : les chiens jouent-ils calmement ? Les propriétaires sont-ils attentifs ? Entrez quand c'est calme. Restez attentif au langage corporel de {dog_name} et intervenez si le jeu s'intensifie trop. Quittez le parc si l'ambiance devient tendue. Un mauvais parc peut faire plus de mal que de bien." },
    { id: 'BE_SOCIAL_007', title: '{dog_name} et les autres espèces', body: "Chats, poules, chevaux, lapins — {dog_name} peut croiser d'autres espèces en promenade ou à la maison. Chaque nouvelle espèce doit être introduite à distance et sous contrôle. Récompensez {dog_name} quand il observe calmement. Ne laissez jamais un chien non supervisé avec un petit animal. L'instinct de chasse est naturel chez certaines races. La cohabitation est possible mais demande de l'encadrement et du respect des instincts de chacun." },
    { id: 'BE_SOCIAL_008', title: '{dog_name} et les enfants inconnus', body: "Les enfants bougent vite, crient et font des gestes imprévisibles — ce qui peut déconcerter {dog_name}. Apprenez-lui que les enfants sont associés à de bonnes choses (friandises à distance). Ne laissez jamais un enfant inconnu approcher {dog_name} sans votre accord. Supervisez toujours les interactions. Si {dog_name} semble inconfortable, éloignez-le calmement. Un chien à l'aise avec les enfants est un chien qui a été exposé progressivement et positivement." },
    { id: 'BE_SOCIAL_009', title: 'La promenade en groupe', body: "Promener {dog_name} avec d'autres chiens est un excellent exercice de socialisation. En marchant côte à côte, les chiens partagent une activité sans la pression du face-à-face. Commencez avec un seul chien calme et compatible. Marchez en parallèle à quelques mètres de distance, puis rapprochez-vous progressivement. La promenade en groupe crée des liens naturels entre chiens sans l'intensité du jeu libre. C'est souvent la meilleure façon de socialiser un chien réactif." },
    { id: 'BE_SOCIAL_010', title: 'Aider un chien craintif', body: "Si {dog_name} est craintif, votre rôle est d'être son pilier de sécurité. Ne le forcez jamais vers ce qui lui fait réaction d’évitement. Restez calme et confiant — votre sérénité le rassure. Récompensez chaque initiative courageuse, même infime. Un regard vers le stimulus ? Friandise. Un pas en avant ? Super friandise. Le travail est long mais chaque petite victoire construit la confiance de {dog_name}. Un éducateur canin spécialisé peut grandement accélérer le processus." },
    { id: 'BE_SOCIAL_011', title: 'Le chien trop joueur qui dérange', body: "Si {dog_name} est trop enthousiaste et bouscule les autres chiens, il faut lui apprendre les codes. Interrompez le jeu quand il devient trop intense — une pause de 10 secondes suffit. Récompensez les moments de calme entre les jeux. Choisissez des partenaires de jeu qui savent poser des limites — un chien adulte équilibré est le meilleur professeur. {dog_name} n'est pas méchant, il a juste besoin d'apprendre les bonnes manières canines." },
    { id: 'BE_SOCIAL_012', title: 'Habituer {dog_name} aux bruits urbains', body: "La ville est un concert permanent : klaxons, sirènes, travaux, musique de rue. Pour que {dog_name} soit à l'aise en ville, exposez-le progressivement. Commencez par des rues calmes, puis augmentez l'activité. Récompensez le calme face aux bruits. Si un bruit fait sursauter {dog_name}, ne surréagissez pas — restez détendu et continuez. Avec l'habitude, les bruits urbains deviennent un bruit de fond anodin." },
    { id: 'BE_SOCIAL_013', title: '{dog_name} dans la foule', body: "Marchés, brocantes, fêtes de village — les foules peuvent être stimulantes ou inquiétantes pour {dog_name}. Commencez en périphérie et observez ses réactions. S'il est détendu, avancez un peu. S'il se raidit, recule ou tire, éloignez-vous. Protégez-le des gens qui veulent le caresser sans demander. Tenez la laisse courte mais détendue. Certains chiens adorent les foules, d'autres non — respectez la personnalité de {dog_name}." },
    { id: 'BE_SOCIAL_014', title: 'Voyager avec {dog_name} : socialisation en mouvement', body: "Voyager expose {dog_name} à de nouveaux environnements, odeurs et sons — c'est une socialisation naturelle. Commencez par de courts trajets et augmentez progressivement. Emportez ses affaires familières (panier, jouet, couverture) pour le rassurer. Chaque nouveau lieu est une opportunité d'apprentissage : la gare, l'hôtel, le restaurant en terrasse. Les premiers voyages posent les bases d'un chien voyageur serein pour la vie." },
    { id: 'BE_SOCIAL_015', title: 'Chiens réactifs : comprendre et respecter', body: "Si vous croisez un chien qui aboie ou tire en laisse, ce n'est pas un mauvais chien ni un mauvais propriétaire. C'est un chien en apprentissage. Éloignez-vous calmement pour leur donner de l'espace. Ne laissez pas {dog_name} s'approcher d'un chien réactif — cela compliquerait leur travail. Un jour, c'est peut-être vous qui aurez besoin de cet espace. La communauté canine fonctionne mieux quand chacun respecte les besoins des autres." },
  ];
  return topics.map(t => ({
    id: t.id, category: 'behavior_education' as const, subcategory: 'socialization',
    breedFilter: [] as string[], sizeFilter: [] as string[], ageMinMonths: null as number | null, ageMaxMonths: null as number | null,
    seasonFilter: [] as string[], monthFilter: [] as number[], regionFilter: ['all'],
    titleFr: t.title, bodyFr: t.body, sourceType: 'behavior_tip' as const,
    neverSay: [...NS], suffix: null as string | null, requiresVetDisclaimer: false,
    channel: 'home_insight' as const, priority: 5, cooldownHours: 252, maxPerMonth: 2,
    usesDogName: true, usesBreedName: true, usesAge: false, usesLocation: false, usesSeason: false,
  }));
}

function generateSeparationTemplates() {
  const topics = [
    { id: 'BE_SEPAR_001', title: 'Le détachement progressif', body: "Apprendre à {dog_name} à rester seul est un processus graduel. Commencez par de très courtes absences : quittez la pièce 10 secondes, revenez. Augmentez lentement la durée. Ne faites pas d'adieux émouvants — sortez naturellement. {dog_name} doit comprendre que vos départs sont normaux et que vous revenez toujours. Ce travail se fait sur des semaines, pas des jours. La clé est de ne jamais dépasser le seuil où {dog_name} devient inconfortable." },
    { id: 'BE_SEPAR_002', title: 'Les premiers moments seul', body: "Si {dog_name} n'a jamais été seul, ne le laissez pas huit heures d'un coup le premier jour. Commencez par cinq minutes, puis dix, puis trente. Laissez-lui un jouet d'occupation (Kong fourré, tapis de léchage). Partez et revenez sans fanfare. Si vous revenez et que tout va bien — pas de destruction, pas de vocalisation — vous pouvez augmenter la durée. Si {dog_name} a du mal, réduisez et progressez plus lentement." },
    { id: 'BE_SEPAR_003', title: 'Reconnaître le mal-être en l\'absence', body: "Comment savoir si {dog_name} vit mal vos absences ? Les signes : destructions ciblées (porte, fenêtre), vocalisation prolongée, malpropreté alors qu'il est propre habituellement, halètement et salivation excessive. Une caméra est un outil précieux pour observer ce qui se passe vraiment. Si {dog_name} se couche et dort après votre départ, tout va bien. S'il tourne en rond et vocalise pendant des heures, un travail spécifique est nécessaire avec un professionnel du comportement." },
    { id: 'BE_SEPAR_004', title: 'Le rituel de départ', body: "Créez un rituel de départ calme et prévisible. Cinq minutes avant de partir, donnez un jouet d'occupation à {dog_name}. Prenez vos affaires sans précipitation. Sortez sans le regarder ni lui parler. Pas de « sois sage » ni de câlin appuyé — cela augmente l'importance de votre départ. Le même rituel chaque jour permet à {dog_name} d'anticiper sereinement : jouet d'occupation = vous partez = vous revenez." },
    { id: 'BE_SEPAR_005', title: 'Le rituel de retour', body: "Quand vous rentrez, ignorez {dog_name} pendant les deux premières minutes. Posez vos affaires, enlevez votre manteau, puis saluez-le calmement. Si vous faites la fête à chaque retour, vous augmentez le contraste entre votre absence et votre présence — ce qui rend l'absence plus difficile. Votre retour doit être un non-événement. {dog_name} apprendra que vos allers-retours sont une routine banale, pas un drame." },
    { id: 'BE_SEPAR_006', title: 'Enrichissement pendant l\'absence', body: "Avant de laisser {dog_name} seul, préparez son environnement. Un Kong fourré de pâtée congelée peut l'occuper 30 minutes. Un tapis de fouille avec des croquettes cachées stimule son odorat. Laissez la radio ou une musique calme en fond sonore. Variez les jouets d'occupation pour maintenir l'intérêt. L'objectif : que {dog_name} associe votre départ à quelque chose de positif et d'occupant, pas à un vide." },
    { id: 'BE_SEPAR_007', title: 'Combien de temps {dog_name} peut-il rester seul ?', body: "La durée maximale dépend de l'âge, de la race et de l'individu. Un chiot ne devrait pas rester seul plus de 2-3 heures. Un adulte bien habitué peut gérer 4-6 heures, avec une sortie pipi avant et après. Au-delà de 6-8 heures, c'est long pour n'importe quel chien. Si vos journées sont longues, envisagez un dog-sitter, une garderie ou un promeneur qui passe en milieu de journée. {dog_name} mérite de ne pas attendre trop longtemps." },
    { id: 'BE_SEPAR_008', title: '{dog_name} pleure quand vous partez', body: "Si {dog_name} vocalise à votre départ, ne revenez pas immédiatement — cela renforcerait le comportement. Mais n'ignorez pas non plus un chien en réelle détresse. La nuance est importante. Un gémissement court qui s'arrête après quelques minutes est normal. Des vocalises intenses qui durent des heures sont un signe de mal-être profond. Utilisez une caméra pour évaluer la situation réelle et adaptez votre approche en conséquence." },
    { id: 'BE_SEPAR_009', title: 'Ne pas en faire un événement', body: "Votre énergie influence directement celle de {dog_name}. Si vous êtes tendu et en retrait en partant, il le présente. Si vous êtes culpabilisé et surexcité en revenant, il associe ces moments à de l'intensité émotionnelle. Partez comme si vous alliez juste vérifier la boîte aux lettres. Revenez comme si vous étiez parti cinq minutes. La banalisation de vos départs et retours est le meilleur cadeau que vous puissiez faire à {dog_name}." },
    { id: 'BE_SEPAR_010', title: '{dog_name} détruit en votre absence', body: "La destruction en l'absence est un signal, pas un caprice. Soit {dog_name} manque d’occupation (destructions variées, jouets, coussins), soit il est en détresse (destructions ciblées sur les sorties — porte, fenêtre, plinthe). Dans le premier cas, augmentez l'enrichissement et l'exercice avant votre départ. Dans le second, le travail est plus profond et nécessite souvent l'aide d'un éducateur comportementaliste. Ne punissez jamais au retour — {dog_name} ne peut pas faire le lien." },
    { id: 'BE_SEPAR_011', title: 'Utiliser une caméra pour observer {dog_name}', body: "Une caméra connectée est un outil précieux pour comprendre le comportement de {dog_name} en votre absence. Vous saurez s'il dort paisiblement après votre départ ou s'il tourne en rond pendant des heures. Certaines caméras permettent de lui parler — à utiliser avec parcimonie, car votre voix sans votre présence peut parfois l'agiter plus. L'observation objective vous permet d'ajuster votre approche et de mesurer les progrès." },
    { id: 'BE_SEPAR_012', title: 'Habituer progressivement à la solitude', body: "L'habituation à la solitude est un entraînement, pas un événement. Pratiquez des mini-séparations quotidiennes. Fermez la porte de la salle de bain quand vous y allez. Allez chercher le courrier. Sortez la poubelle. Chaque micro-absence sans drame construit la confiance de {dog_name}. Augmentez la durée très graduellement. Si à un moment {dog_name} montre des signes d'inconfort, revenez en arrière et reprenez plus lentement. La patience paie toujours." },
    { id: 'BE_SEPAR_013', title: '{dog_name} aboie quand il est seul', body: "Si les voisins vous signalent que {dog_name} aboie en votre absence, c'est un signal à prendre au sérieux. Déterminez d'abord la cause : ennui, bruits extérieurs ou mal-être. Un chien qui aboie par ennui bénéficiera d'enrichissement et d'exercice accru. Un chien qui réagit aux bruits peut être aidé par un fond sonore (radio, musique). Un chien en réelle détresse nécessite un travail de fond sur la séparation. Ne punissez jamais l'aboiement au retour." },
    { id: 'BE_SEPAR_014', title: 'Retour au bureau après le télétravail', body: "Après des mois de présence constante, {dog_name} s'est habitué à vous avoir à la maison. Le retour au bureau peut être un choc. Préparez-le en avance : commencez à vous absenter régulièrement, même pour de courts moments. Réintroduisez progressivement la routine « bureau ». Prenez vos clés, mettez votre manteau et sortez 15 minutes. Augmentez la durée. Le jour du retour au bureau, {dog_name} sera préparé. Si possible, envisagez un retour progressif (quelques jours par semaine)." },
    { id: 'BE_SEPAR_015', title: 'Le chiot et la solitude', body: "Un chiot n'a jamais connu la solitude avant d'arriver chez vous. Tout est nouveau et la séparation peut être effrayante. Ne laissez pas un très jeune chiot seul des heures d'emblée. Commencez par de très courtes absences dans une autre pièce. Laissez un vêtement qui porte votre odeur dans son panier. Proposez un Kong fourré au départ. Augmentez la durée très progressivement. Un chiot qui apprend tôt que la solitude est supportable sera un adulte serein." },
  ];
  return topics.map(t => ({
    id: t.id, category: 'behavior_education' as const, subcategory: 'separation',
    breedFilter: [] as string[], sizeFilter: [] as string[], ageMinMonths: null as number | null, ageMaxMonths: null as number | null,
    seasonFilter: [] as string[], monthFilter: [] as number[], regionFilter: ['all'],
    titleFr: t.title, bodyFr: t.body, sourceType: 'behavior_tip' as const,
    neverSay: [...NS], suffix: null as string | null, requiresVetDisclaimer: false,
    channel: 'home_insight' as const, priority: 6, cooldownHours: 252, maxPerMonth: 2,
    usesDogName: true, usesBreedName: true, usesAge: false, usesLocation: false, usesSeason: false,
  }));
}
